{
  "name": "回环通信器",
  "name_en": "Loopback Communicator",
  "manufacturer": "",
  "description": "一种用于仪器通信测试的虚拟回环通信接口，通过标准输入/输出模拟原始数据读写。在未连接实际仪器时，可用于单元测试、接口探索以及开发调试。",
  "description_en": "A virtual loopback communication interface for instrument communication testing. It simulates raw data read/write through standard input and output, and is used for unit testing, API exploration, and development debugging when no physical instrument is connected.",
  "tag_hints": [
    "loopback communication",
    "instrument API testing",
    "unit testing",
    "virtual I/O",
    "mock instrument connection",
    "stdin stdout transport"
  ],
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取/设置地址",
      "description_en": "get/set address"
    },
    {
      "action_name": "auto-close",
      "description": "关闭回环连接",
      "description_en": "close the loopback connection"
    },
    {
      "action_name": "auto-flush_input",
      "description": "清空输入缓冲区",
      "description_en": "flush the input buffer"
    },
    {
      "action_name": "auto-read_raw",
      "description": "读取原始输入数据",
      "description_en": "read raw input data"
    },
    {
      "action_name": "auto-seek",
      "description": "移动输入数据位置",
      "description_en": "seek to an input data position"
    },
    {
      "action_name": "auto-tell",
      "description": "获取当前输入数据位置",
      "description_en": "get the current input data position"
    },
    {
      "action_name": "auto-terminator",
      "description": "获取/设置终止字符",
      "description_en": "get/set terminator"
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置超时时间",
      "description_en": "get/set timeout"
    },
    {
      "action_name": "auto-write_raw",
      "description": "写入原始输出数据",
      "description_en": "write raw output data"
    }
  ]
}

